package pycompat

import (
	_ "embed"
	"sort"
	"strconv"
	"strings"
	"sync"
	"unicode/utf8"

	"github.com/angeles725/niagara-go/internal/textfold"
)

// unicodeData was generated by the retired testdata/gen.py from the Python the fixtures were made with;
// its first line names that Python and Unicode version.
//
//go:embed unicode.txt
var unicodeData string

type runeRange struct{ lo, hi rune }

type tables struct {
	header                                    string
	alpha, decimal, digit, numeric, printable []runeRange
	// CPython's case flags (as the retired gen.py derived them): upper, lower, title (or upper and lower).
	upper, lower, title []runeRange
}

var data = sync.OnceValue(func() *tables { return parseTables(unicodeData) })

func parseTables(text string) *tables {
	t := &tables{}
	for _, line := range strings.Split(text, "\n") {
		if line == "" {
			continue
		}
		if line[0] == '#' {
			t.header = line
			continue
		}
		f := strings.Fields(line)
		var dst *[]runeRange
		switch f[0] {
		case "A":
			dst = &t.alpha
		case "D":
			dst = &t.decimal
		case "G":
			dst = &t.digit
		case "N":
			dst = &t.numeric
		case "P":
			dst = &t.printable
		case "U":
			dst = &t.upper
		case "L":
			dst = &t.lower
		case "T":
			dst = &t.title
		default:
			panic("pycompat: corrupt unicode.txt line " + strconv.Quote(line))
		}
		for _, e := range f[1:] {
			lo, hi, ok := strings.Cut(e, "-")
			if !ok {
				panic("pycompat: corrupt unicode.txt entry " + strconv.Quote(e))
			}
			*dst = append(*dst, runeRange{parseHex(lo), parseHex(hi)})
		}
	}
	return t
}

func parseHex(h string) rune {
	v, err := strconv.ParseUint(h, 16, 32)
	if err != nil {
		panic("pycompat: corrupt unicode.txt code point " + strconv.Quote(h))
	}
	return rune(v)
}

// find returns the range holding r, or -1.
func find(rs []runeRange, r rune) int {
	i := sort.Search(len(rs), func(i int) bool { return rs[i].hi >= r })
	if i < len(rs) && rs[i].lo <= r {
		return i
	}
	return -1
}

func isASCIILetter(r rune) bool { return 'a' <= r && r <= 'z' || 'A' <= r && r <= 'Z' }

// IsAlpha is str.isalpha() for one code point.
func IsAlpha(r rune) bool {
	if r < utf8.RuneSelf {
		return isASCIILetter(r)
	}
	return find(data().alpha, r) >= 0
}

// IsDecimal is str.isdecimal() for one code point (the digits int() and float() accept).
func IsDecimal(r rune) bool {
	if r < utf8.RuneSelf {
		return '0' <= r && r <= '9'
	}
	return find(data().decimal, r) >= 0
}

// IsDigit is str.isdigit() for one code point.
func IsDigit(r rune) bool {
	if r < utf8.RuneSelf {
		return '0' <= r && r <= '9'
	}
	return find(data().digit, r) >= 0
}

// IsNumeric is str.isnumeric() for one code point.
func IsNumeric(r rune) bool {
	if r < utf8.RuneSelf {
		return '0' <= r && r <= '9'
	}
	return find(data().numeric, r) >= 0
}

// IsAlnum is str.isalnum() for one code point: alpha, decimal, digit or numeric.
func IsAlnum(r rune) bool {
	if r < utf8.RuneSelf {
		return isASCIILetter(r) || '0' <= r && r <= '9'
	}
	return IsAlpha(r) || IsDecimal(r) || IsDigit(r) || IsNumeric(r)
}

// IsWordRune is re's \w on str patterns: str.isalnum() or '_'.
func IsWordRune(r rune) bool { return r == '_' || IsAlnum(r) }

// IsPrintable is str.isprintable() for one code point (what repr() leaves unescaped).
func IsPrintable(r rune) bool {
	if r < utf8.RuneSelf {
		return r >= 0x20 && r < 0x7f
	}
	return find(data().printable, r) >= 0
}

// SpaceClass is the body of an RE2 character class (no brackets) that matches exactly the
// str.isspace() code points: Python re's \s on str patterns, for "[" + SpaceClass() + "]".
func SpaceClass() string { return spaceClass() }

var spaceClass = sync.OnceValue(func() string {
	rs := textfold.Spaces()
	var b strings.Builder
	for i := 0; i < len(rs); {
		j := i
		for j+1 < len(rs) && rs[j+1] == rs[j]+1 {
			j++
		}
		b.WriteString(`\x{` + strconv.FormatInt(int64(rs[i]), 16) + `}`)
		if j > i {
			b.WriteString(`-\x{` + strconv.FormatInt(int64(rs[j]), 16) + `}`)
		}
		i = j + 1
	}
	return b.String()
})

// decimalValue is the digit value of a str.isdecimal() code point, -1 otherwise. Every
// Unicode Nd block is a run of ten starting at its zero, so ranges stay aligned.
func decimalValue(r rune) int {
	if '0' <= r && r <= '9' {
		return int(r - '0')
	}
	if r < utf8.RuneSelf {
		return -1
	}
	rs := data().decimal
	i := find(rs, r)
	if i < 0 {
		return -1
	}
	return int(r-rs[i].lo) % 10
}
